3: /// Сигнал для вкладок главного экрана: одновременное обновление курса валют и ленты новостей.
4: class RefreshAllSignal extends ChangeNotifier {
5:   void refreshAll() => notifyListeners();
6: }
7: 
8: class HomePage extends StatefulWidget {
9:   const HomePage({super.key, this.refreshAllSignal});
10: 
11:   final RefreshAllSignal? refreshAllSignal;
12: 
13:   @override
14:   State<HomePage> createState() => _HomePageState();
15: }
16: 
17: class _HomePageState extends State<HomePage> {
18:   int _selectedIndex = 0;
19: 
20:   late final RefreshAllSignal _refreshAllSignal = widget.refreshAllSignal ?? RefreshAllSignal();
21: 
22:   late final List<Widget> _pages = <Widget>[
23:     CurrencyListPage(refreshAllSignal: _refreshAllSignal),
24:     NewsListPage(refreshAllSignal: _refreshAllSignal),
25:     const ProfilePage(),
26:   ];
27: 
28:   @override
29:   void dispose() {
30:     if (widget.refreshAllSignal == null) _refreshAllSignal.dispose();
31:     super.dispose();
32:   }
33: 
34:   void _onItemTapped(int index) {
35:     setState(() {
36:       _selectedIndex = index;
37:     });
38:   }
39: 
40:   /// Запускает одновременное обновление курса валют и ленты новостей из сети.
41:   void _onRefreshAllPressed() => _refreshAllSignal.refreshAll();
42: 
43:   @override
44:   Widget build(BuildContext context) {
45:     final Widget currentPage = _pages[_selectedIndex];
46:     final AppLocalizations loc = context.loc;
47:     final ThemeFonts fonts = context.fonts;
48: 
49:     return Scaffold(
50:       body: currentPage,
51:       bottomNavigationBar: Container(
52:         decoration: BoxDecoration(
53:           boxShadow: <BoxShadow>[
54:             BoxShadow(
55:               color: context.colors.bottomNavBarShadow,
56:               blurRadius: 25,
57:               offset: Offset(0.0, 0.75),
58:             ),
59:           ],
60:         ),
61:         child: Column(
62:           mainAxisSize: MainAxisSize.min,
63:           children: [
64:             Padding(
65:               padding: const EdgeInsets.fromLTRB(22, 12, 22, 4),
66:               child: SizedBox(
67:                 width: double.infinity,
68:                 child: ElevatedButton(
69:                   onPressed: _onRefreshAllPressed,
70:                   child: Text(
71:                     loc.refreshAll,
72:                     style: fonts.regular14,
73:                   ),
74:                 ),
75:               ),
76:             ),
77:             BottomNavigationBar(
78:               currentIndex: _selectedIndex,
79:               onTap: _onItemTapped,
80:               items: [
81:                 BottomNavigationBarItem(
82:                   icon: TabWidget(
83:                     assetPath: 'assets/icons/home.png',
84:                     isSelected: currentPage is CurrencyListPage,
85:                   ),
86:                   label: loc.currencyRate,
87:                 ),
88:                 BottomNavigationBarItem(
89:                   icon: TabWidget(
90:                     assetPath: 'assets/icons/news.png',
91:                     isSelected: currentPage is NewsListPage,
92:                   ),
93:                   label: loc.news,
94:                 ),
95:                 BottomNavigationBarItem(
96:                   icon: Icon(Icons.person),
97:                   label: loc.profile,
98:                 ),
99:               ],
100:             ),
101:           ],
102:         ),
103:       ),
104:     );
105:   }
106: }
107: 
