130: }

1: import 'package:mad_flutter_practicum/app/app.dart';
2: import 'package:mad_flutter_practicum/domain/domain.dart';
3: 
4: import 'widgets/widgets.dart';
5: 
6: class NewsListPage extends StatefulWidget {
7:   const NewsListPage({super.key, this.refreshAllSignal});
8: 
9:   final RefreshAllSignal? refreshAllSignal;
10: 
11:   @override
12:   State<NewsListPage> createState() => _NewsListPageState();
13: }
14: 
15: class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
16:   static final _tween = Tween<double>(begin: 0.25, end: 1);
17: 
18:   late Future<List<NewsModel>> _newsListFuture;
19: 
20:   late final AnimationController _scaleController;
21:   late final Animation<double> _scaleAnimation;
22: 
23:   @override
24:   void initState() {
25:     super.initState();
26:     _initAnimation();
27:     _initData();
28:     widget.refreshAllSignal?.addListener(_refresh);
29:   }
30: 
31:   @override
32:   void dispose() {
33:     widget.refreshAllSignal?.removeListener(_refresh);
34:     _scaleController.dispose();
35:     super.dispose();
36:   }
37: 
38:   @override
39:   void didUpdateWidget(NewsListPage oldWidget) {
40:     super.didUpdateWidget(oldWidget);
41:     if (oldWidget.refreshAllSignal != widget.refreshAllSignal) {
42:       oldWidget.refreshAllSignal?.removeListener(_refresh);
43:       widget.refreshAllSignal?.addListener(_refresh);
44:     }
45:   }
46: 
47:   void _initAnimation() {
48:     _scaleController = AnimationController(
49:       vsync: this,
50:       duration: Duration(milliseconds: 200),
51:     );
52:     _scaleAnimation = _tween.animate(_scaleController);
53:   }
54: 
55:   Future<List<NewsModel>> _loadNewsFeed() {
56:     final newsRepository = context.read<NewsRepository>();
57:     final Future<List<NewsModel>> newsFeed = newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true));
58: 
59:     return newsFeed.then((List<NewsModel> value) {
60: 
61:       _scaleController.forward(); // запускаем анимацию
62: 
63:       return value;
64:     }).catchError((Object _) {
65:       // Ошибку запроса показывает FutureBuilder; для RefreshIndicator важно лишь завершить Future.
66:       return <NewsModel>[];
67:     });
68:   }
69: 
70:   void _initData() {
71:     _newsListFuture = _loadNewsFeed();
72:   }
73: 
74:   /// Перезагружает ленту новостей из сети по сигналу «Обновить всё».
75:   Future<void> _refresh() async {
76:     _scaleController.reset();
77: 
78:     setState(() {
79:       _newsListFuture = _loadNewsFeed();
80:     });
81: 
82:     await _newsListFuture;
83:   }
84: 
85:   @override
86:   Widget build(BuildContext context) {
87:     return Scaffold(
88:       appBar: AppBar(title: Text(context.loc.news)),
89:       body: FutureBuilder<List<NewsModel>>(
90:         future: _newsListFuture,
91:         builder: (BuildContext context, AsyncSnapshot<List<NewsModel>> snapshot) {
92:           final List<NewsModel>? data = snapshot.data;
93:           if (data == null) return const SizedBox.shrink();
94: 
95:           return ScaleTransition(
96:             scale: _scaleAnimation,
97:             child: RefreshIndicator(
98:               onRefresh: _refresh,
99:               color: context.colors.currencyCardSymbolBackground,
100:               child: ListView.builder(
101:                 itemCount: data.length,
102:                 itemBuilder: (BuildContext context, int index) {
103:                   final NewsModel news = data[index];
104: 
105:                   return Padding(
106:                     key: ValueKey(news.link),
107:                     padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
108:                     child: NewsCard(model: news),
109:                   );
110:                 },
